// Unify Hacker News, dev.to and Lobste.rs responses into one story schema.
// Items that do not match a known shape (for example a failed source that
// returned an error item) are skipped, so one dead source never kills the run.
var out = [];
var all = $input.all();
for (var k = 0; k < all.length; k++) {
  var j = all[k].json;
  if (j && Array.isArray(j.hits)) {
    for (var a = 0; a < j.hits.length; a++) {
      var h = j.hits[a];
      if (!h.title || !h.url) continue;
      out.push({ json: {
        title: String(h.title),
        url: h.url,
        points: h.points || 0,
        comments: h.num_comments || 0,
        published_at: h.created_at,
        author: h.author || 'unknown',
        source: 'Hacker News'
      }});
    }
  } else if (Array.isArray(j) && j.length > 0 && j[0] && j[0].short_id) {
    for (var e = 0; e < j.length; e++) {
      var lb = j[e];
      if (!lb.title || !lb.url) continue;
      out.push({ json: {
        title: String(lb.title),
        url: lb.url,
        points: lb.score || 0,
        comments: lb.comment_count || 0,
        published_at: lb.created_at,
        author: lb.submitter_user || 'unknown',
        source: 'Lobste.rs'
      }});
    }
  } else if (Array.isArray(j)) {
    for (var b = 0; b < j.length; b++) {
      var art = j[b];
      if (!art || !art.title || !art.url) continue;
      out.push({ json: {
        title: String(art.title),
        url: art.url,
        points: art.positive_reactions_count || 0,
        comments: art.comments_count || 0,
        published_at: art.published_at,
        author: (art.user && art.user.name) || 'unknown',
        source: 'dev.to'
      }});
    }
  }
}
var capped = [];
var seenUrl = {};
for (var m = 0; m < out.length && capped.length < 150; m++) {
  var u = out[m].json.url;
  if (!u || seenUrl[u]) continue;
  seenUrl[u] = true;
  capped.push(out[m]);
}
return capped;

// Drop stories already sent in previous runs.
// Sent URLs are tracked in workflow static data (persists on active workflows).
var staticData = $getWorkflowStaticData('global');
var sent = staticData.sentUrls || [];
var fresh = [];
var all = $input.all();
for (var i = 0; i < all.length; i++) {
  var url = all[i].json.url || '';
  if (url && sent.indexOf(url) === -1) fresh.push(all[i]);
}
return fresh;

// Score each story: engagement * recency decay * AI-keyword boost, then sort.
// Recency uses exponential decay with a 48h time constant so fresh, hot
// stories surface even when an older story has more raw points.
var keywords = ['llm','gpt','agent','rag','diffusion','transformer','openai','anthropic','gemini','gemma','llama','mistral','copilot','chatbot','embedding','fine-tune','finetune','alignment','safety','robot','nvidia','hugging'];
var now = Date.now();
var all = $input.all();
var scored = [];
for (var i = 0; i < all.length; i++) {
  var s = all[i].json;
  var ageMs = now - Date.parse(s.published_at || 0);
  if (!(ageMs > 0)) ageMs = 3600000;
  var decay = Math.exp(-(ageMs / 3600000) / 48);
  var t = (s.title || '').toLowerCase();
  var boost = 1.0;
  for (var k = 0; k < keywords.length; k++) {
    if (t.indexOf(keywords[k]) !== -1) { boost = 1.5; break; }
  }
  var score = (s.points + s.comments * 2) * decay * boost;
  var copy = {};
  for (var key in s) copy[key] = s[key];
  copy.score = Math.round(score * 100) / 100;
  scored.push({ json: copy });
}
scored.sort(function(a, b) { return b.json.score - a.json.score; });
return scored;

// Take the top N stories and stash them for the history saver and the
// AI-fallback path (both read workflow static data later in this run).
var cfg = $('Configuration').first().json;
var maxStories = cfg.maxStories || 8;
var all = $input.all();
var top = all.slice(0, maxStories);
var staticData = $getWorkflowStaticData('global');
staticData.lastSentBatch = [];
staticData.lastStories = [];
for (var i = 0; i < top.length; i++) {
  var s = top[i].json;
  if (s.url) staticData.lastSentBatch.push(s.url);
  staticData.lastStories.push(s);
}
return top;

// Build the structured analysis prompt for the AI editor.
var stories = $input.all().map(function(i) { return i.json; });
var lines = [];
for (var i = 0; i < stories.length; i++) {
  var s = stories[i];
  lines.push((i + 1) + '. [' + s.source + '] ' + s.title + ' (' + s.points + ' pts, ' + s.comments + ' comments) ' + s.url);
}
var prompt = 'You are a senior tech news editor. Analyze these AI news stories from today.\n\n'
  + 'STORIES:\n' + lines.join('\n') + '\n\n'
  + 'Return ONLY valid JSON, no markdown fences, no commentary, with this exact shape:\n'
  + '{"executive_take": "2-3 sentences on the single biggest theme of the day", "categories": [{"name": "category name", "stories": [{"title": "story title", "url": "story url", "one_liner": "one punchy sentence summary", "why_it_matters": "one sentence on significance"}]}]}\n\n'
  + 'Rules: group stories into 3-5 tight categories (examples: LLMs, AI Agents, Tools and Products, Research, Business). '
  + 'Keep each one_liner under 25 words. Plain language, no hype, no emojis. Every input story must appear exactly once.';
return [{ json: { prompt: prompt, storyCount: stories.length } }];

// Parse the model JSON. Any failure (model error item, bad JSON, wrong
// shape) degrades gracefully to a headlines-only briefing instead of
// crashing the run.
function fallback(reason) {
  var staticData = $getWorkflowStaticData('global');
  var stories = staticData.lastStories || [];
  var lines = [];
  for (var i = 0; i < stories.length; i++) {
    lines.push((i + 1) + '. ' + stories[i].title + ' - ' + stories[i].url);
  }
  return [{ json: { fallbackText: 'AI analysis was unavailable for this run (' + reason + '). Here are the top stories as headlines:\n\n' + lines.join('\n') } }];
}
var first = $input.first().json;
if (first && first.error) return fallback('the model call failed');
var raw = '';
try { raw = first.message.content; } catch (e) { raw = ''; }
var cleaned = String(raw || '').trim();
var fence = String.fromCharCode(96, 96, 96);
if (cleaned.indexOf(fence) === 0) {
  cleaned = cleaned.split(fence).join('').trim();
}
try {
  var parsed = JSON.parse(cleaned);
  if (!parsed || !parsed.categories) throw new Error('bad shape');
  return [{ json: { analysis: parsed } }];
} catch (e) {
  return fallback('the model returned unparseable output');
}

// Format the briefing as Telegram Markdown and split into 4000-char
// chunks on line boundaries (Telegram caps messages at 4096 chars).
function esc(t) {
  return String(t || '').split('*').join('\\*').split('_').join('\\_').split('[').join('\\[').split(']').join('\\]');
}
var input = $input.first().json;
var cfg = $('Configuration').first().json;
var title = cfg.briefingTitle || 'Daily AI Briefing';
var today = new Date().toISOString().slice(0, 10);
var body = '';
if (input.analysis) {
  var a = input.analysis;
  body = '*' + esc(title) + '* - ' + esc(today) + '\n\n';
  body += '_' + esc(a.executive_take || '') + '_\n';
  var cats = a.categories || [];
  for (var c = 0; c < cats.length; c++) {
    var cat = cats[c];
    body += '\n*' + esc(cat.name) + '*\n';
    var stories = cat.stories || [];
    for (var s = 0; s < stories.length; s++) {
      var st = stories[s];
      body += '- [' + esc(st.title) + '](' + st.url + ')\n';
      if (st.one_liner) body += '  ' + esc(st.one_liner) + '\n';
      if (st.why_it_matters) body += '  _Why it matters:_ ' + esc(st.why_it_matters) + '\n';
    }
  }
} else if (input.fallbackText) {
  body = '*' + esc(title) + '* - ' + esc(today) + '\n\n' + esc(input.fallbackText);
} else {
  body = '*' + esc(title) + '* - ' + esc(today) + '\n\nNo briefing data was produced for this run.';
}
var chunks = [];
var lines = body.split('\n');
var current = '';
for (var i = 0; i < lines.length; i++) {
  if ((current + lines[i] + '\n').length > 4000 && current.length > 0) {
    chunks.push(current);
    current = '';
  }
  current += lines[i] + '\n';
}
if (current.length > 0) chunks.push(current);
return chunks.map(function(ch) { return { json: { message: ch } }; });

// Persist the sent URLs so the next run does not resend them.
// Runs only after the Telegram send succeeds, so failed sends are retried.
var staticData = $getWorkflowStaticData('global');
var sent = staticData.sentUrls || [];
var batch = staticData.lastSentBatch || [];
for (var i = 0; i < batch.length; i++) {
  if (sent.indexOf(batch[i]) === -1) sent.push(batch[i]);
}
staticData.sentUrls = sent.slice(-500);
staticData.lastSentBatch = [];
return $input.all();

// Nothing fresh since the last run: send a short status note instead of
// a briefing, and skip the AI call entirely.
var cfg = $('Configuration').first().json;
var title = cfg.briefingTitle || 'Daily AI Briefing';
var today = new Date().toISOString().slice(0, 10);
return [{ json: { message: '*' + title + '* - ' + today + '\n\nNo fresh AI stories since the last briefing. Everything worth reading was already sent.' } }];
